"""The ONE canonical Rule 13 block, and the only place it is edited.

Rule 13 checks every ``.epyson`` under ``src/<pkg>/_config/``: a typed id equal
to the filename stem, semver ``version``, a real ``description``, a valid
``audit_status``, no BOM, and -- the part that keeps coming back -- no
first-level key holding an empty container.

WHY ONE SOURCE INSTEAD OF SIX COPIES
------------------------------------
The rule was rolled out by INJECTING a block into each library's housekeeper,
and the injector skipped any library that already had one. It could add but
never reconcile, so the copies drifted: no two of the five messages were
identical, and the divergence was not merely cosmetic --

* epy_masonry returned ``[]`` (fail-OPEN) when the package or ``_config/`` was
  missing, where the others reported it;
* epy_masonry measured ``description`` WITHOUT ``.strip()``, so a file padded
  with spaces passed there and failed everywhere else;
* it truncated the offending-key list at 5 where the others used 6;
* it attributed the ``**kwargs`` finding to Rule 13 instead of Rule 9.

epy_aluminum had no Rule 13 at all -- fourteen ungoverned catalogs.

The behaviours below are a deliberate best-of, not a majority vote: fail LOUD
on a missing package, ``.strip()`` the description, and test the
``_constitutive`` exemption against the path RELATIVE to the library root, so an
ancestor directory of that name cannot silently exempt an entire checkout.
"""

from __future__ import annotations

#: Injected verbatim into each housekeeper. It stays a string because the
#: housekeepers are standalone scripts with no dependency on this package --
#: they are SYNCED, not imported.
RULE13_BLOCK = 'def _declared_audit_statuses(pkg: Path) -> set[str]:\n    """Return the audit statuses the library itself declares as valid.\n\n    The four canonical values are the default, and fourteen of the fifteen\n    libraries declare exactly those -- so reading the declaration changes\n    nothing for them. It matters for the one that does not: epy_connections\n    also publishes `published_standard`, for a universally published normative\n    constant used with explicit provenance but not cross-read from a specific\n    PDF page. That was documented in its own schema AND in its own copy of this\n    rule, and a shared block that hardcodes the four would have turned a\n    deliberate, declared category into 1 violation per file.\n\n    The schema is the right source because it is what the loader enforces at\n    read time; a gate that disagrees with it is testing a different rule.\n    """\n    default = {"verified", "partial", "needs_source_verification", "n_a"}\n    for schema in sorted(pkg.rglob("*_schema*.py")) + sorted(pkg.rglob("_schemas/_base.py")):\n        text = schema.read_text(encoding="utf-8", errors="ignore")\n        match = re.search(r"VALID_AUDIT_STATUS\\s*=\\s*frozenset\\(\\s*\\{(.*?)\\}", text, re.S)\n        if match:\n            declared = set(re.findall(r\'"([a-z_]+)"\', match.group(1)))\n            if declared:\n                return declared\n    return default\n\n\ndef audit_epyson_canon(lib_root: Path) -> list[str]:\n    """Verify every `.epyson` under `src/<pkg>/_config/` is canonical (Rule 13).\n\n    SYNCED from _packaging/_tooling/rule13_canon_block.py -- edit it THERE and\n    re-run add_hk_rule13_xsuite.py --apply. A local edit here is overwritten.\n    """\n    import json as _json\n\n    pkg = _find_pkg_dir(lib_root)\n    if pkg is None:\n        # Fail LOUD. A silent [] here is indistinguishable from a clean tree,\n        # which is precisely the failure mode this rule exists to catch.\n        return ["src/<pkg>/ not found - Rule 13 cannot audit the catalogs"]\n    config_dir = pkg / "_config"\n    if not config_dir.is_dir():\n        return ["src/<pkg>/_config/ not found - Rule 13 cannot audit the catalogs"]\n\n    valid_audit = _declared_audit_statuses(pkg)\n    semver = re.compile(r"^\\d+\\.\\d+\\.\\d+([.\\-+].*)?$")\n    violations: list[str] = []\n\n    for p in sorted(config_dir.rglob("*.epyson")):\n        rel = p.relative_to(lib_root)\n        try:\n            raw = p.read_bytes()\n            if raw.startswith(b"\\xef\\xbb\\xbf"):\n                violations.append(f"{rel}: UTF-8 BOM present - strip it")\n                raw = raw[3:]\n            data = _json.loads(raw.decode("utf-8"))\n        except Exception as e:\n            violations.append(f"{rel}: JSON parse error - {e}")\n            continue\n        if not isinstance(data, dict):\n            violations.append(f"{rel}: top-level must be a JSON object")\n            continue\n        # Prefer the id the loader validates. A constitutive file carries BOTH\n        # `material_id` (component-prefixed, e.g. `bolt_shear_slip`) and\n        # `constitutive_id` (the law name, which is what must equal the stem);\n        # picking whichever `*_id` came first in the file reported a mismatch\n        # on every one of them. Any other `*_id` is its file type\'s only id.\n        if isinstance(data.get("constitutive_id"), str):\n            id_field = "constitutive_id"\n        else:\n            id_field = next(\n                (\n                    k\n                    for k in data\n                    if isinstance(k, str) and k.endswith("_id") and isinstance(data[k], str)\n                ),\n                None,\n            )\n        if not id_field:\n            violations.append(f"{rel}: missing top-level `<algo>_id` field")\n            continue\n        # A `<id>/manifest.epyson` names its id after the DIRECTORY -- the\n        # layout its own loader enforces (it rejects a manifest whose typed\n        # id differs from its folder). Everywhere else the id is the stem.\n        expected_id = p.parent.name if p.stem == "manifest" else p.stem\n        if data[id_field] != expected_id:\n            violations.append(\n                f"{rel}: id mismatch - \'{id_field}\'=\'{data[id_field]!r}\' must equal \'{expected_id}\'"\n            )\n        v = data.get("version")\n        if not (isinstance(v, str) and semver.match(v)):\n            violations.append(f"{rel}: missing/invalid `version` (got {v!r})")\n        d = data.get("description")\n        if not (isinstance(d, str) and len(d.strip()) >= 20):\n            violations.append(f"{rel}: `description` missing or shorter than 20 chars")\n        a = data.get("audit_status")\n        if a not in valid_audit:\n            violations.append(f"{rel}: `audit_status`={a!r} not in {sorted(valid_audit)}")\n        # Row ids of references.db are FORBIDDEN citations: the db reindexes\n        # and ids silently move (measured 2026-08-20: a catalog pointed at an\n        # unrelated book, another at a nonexistent row). Cite source_file\n        # (filename) + pages instead.\n        def _walk_for_db_ids(obj, path="$"):\n            if isinstance(obj, dict):\n                for k, v in obj.items():\n                    if k == "source_db_id":\n                        violations.append(\n                            f"{rel}: {path}.source_db_id cites a references.db ROW ID, "\n                            f"which rots on reindex -- cite source_file (filename) + pages."\n                        )\n                    _walk_for_db_ids(v, f"{path}.{k}")\n            elif isinstance(obj, list):\n                for i, v in enumerate(obj):\n                    _walk_for_db_ids(v, f"{path}[{i}]")\n        _walk_for_db_ids(data)\n        # Files under `_constitutive` are exempt: there `"points": []` means the law is defined\n        # by an equation and has no tabulated points, and the consuming code indexes that key\n        # directly, so removing it would raise KeyError.\n        if "_constitutive" not in rel.parts:\n            empty_keys = sorted(\n                k for k, val in data.items() if isinstance(val, (dict, list)) and not val\n            )\n            if empty_keys:\n                shown = ", ".join(f"`{k}`" for k in empty_keys[:6])\n                extra = f" (+{len(empty_keys) - 6} more)" if len(empty_keys) > 6 else ""\n                violations.append(\n                    f"{rel}: empty first-level key(s) {shown}{extra} - the suite dispatches on "\n                    f"presence, so an empty object/array makes this code claim a provision it "\n                    f"does not publish; delete the key instead of padding it"\n                )\n\n    loader_path = pkg / "_config" / "_loader.py"\n    if loader_path.is_file():\n        loader_text = loader_path.read_text(encoding="utf-8", errors="ignore")\n        if "_validate_typed_id" not in loader_text:\n            violations.append("_config/_loader.py: missing `_validate_typed_id` usage")\n        if "**kwargs" in loader_text or "**data" in loader_text:\n            violations.append("_config/_loader.py: contains **kwargs / **data (Rule 9 violation)")\n\n    return violations\n\n\ndef report_epyson_canon(violations: list[str]) -> None:\n    if not violations:\n        print(\n            "\\n  .epyson canon (Rule 13): OK (every file has typed-id + version + description + audit_status)"\n        )\n        return\n    print(f"\\n  .epyson canon (Rule 13): {len(violations)} violation(s):")\n    for v in violations[:30]:\n        print(f"    - {v}")\n    if len(violations) > 30:\n        print(f"    ... and {len(violations) - 30} more")\n'
